require_once __DIR__.'/../../core/db_connect.php';require_once __DIR__.'/../../core/bible_studies.php';$user=bs_require_eligible($pdo);
if(!bs_schema_ready($pdo)){http_response_code(503);header('Retry-After: 300');exit('Bible Study setup is not complete.');}
try{$id=bs_positive_int($_GET['material_id']??null,'material');$q=$pdo->prepare('SELECT m.id,m.bible_study_id,m.original_filename,m.storage_key,m.mime_type,m.file_size,m.is_published,b.status FROM bible_study_materials m JOIN bible_studies b ON b.id=m.bible_study_id WHERE m.id=? LIMIT 1');$q->execute([$id]);$m=$q->fetch();if(!$m)throw new RuntimeException('Material not found.');if(!$m['is_published']&&!bs_can_manage($pdo,(int)$m['bible_study_id']))throw new RuntimeException('Material not available.');if($m['status']==='draft'&&!bs_can_manage($pdo,(int)$m['bible_study_id']))throw new RuntimeException('Material not available.');$root=realpath(bs_material_storage_root());$path=$root?realpath($root.'/'.$m['storage_key']):false;if(!$root||!$path||strpos($path,$root.DIRECTORY_SEPARATOR)!==0||!is_file($path))throw new RuntimeException('Material file is unavailable.');header('Content-Type: '.$m['mime_type']);header('Content-Length: '.(string)filesize($path));header('Content-Disposition: attachment; filename="download.'.preg_replace('/[^a-z0-9]/','',strtolower(pathinfo($m['original_filename'],PATHINFO_EXTENSION))).'"; filename*=UTF-8\'\''.rawurlencode($m['original_filename']));header('X-Content-Type-Options: nosniff');header('Cache-Control: private, no-store');readfile($path);exit;}catch(Throwable $e){error_log('[bible_study_download] '.$e->getMessage());http_response_code(404);exit('Material unavailable.');}
